# ---------------------------------------------------------------------------- Fisher
def _logfact_fn(max_n):
    """log(n!) as a vectorised lookup (table up to max_n), exact to ~1e-9."""
    max_n = int(max_n)
    if max_n <= 50_000_000:
        tab = np.zeros(max_n + 2)
        tab[2:] = np.cumsum(np.log(np.arange(2, max_n + 2, dtype=float)))
        return lambda x: tab[np.asarray(x, dtype=np.int64)]
    lg = np.frompyfunc(lambda v: math.lgamma(v + 1.0), 1, 1)
    return lambda x: np.asarray(lg(np.asarray(x, dtype=float)), dtype=float)


def fisher_greater(a, b, c, d):
    """One-sided Fisher exact test, alternative 'greater', for 2x2 tables [[a, b], [c, d]].

    p = P(X >= a), X hypergeometric with the table margins fixed. Same as
    scipy.stats.fisher_exact(table, alternative='greater'). Vectorised over arrays."""
    a, b, c, d = (np.asarray(v, dtype=np.int64) for v in (a, b, c, d))
    n_rows = a.size
    p = np.ones(n_rows)
    if n_rows == 0:
        return p
    N, K, n = a + b + c + d, a + c, a + b                  # population, successes, draws
    lo, hi = np.maximum(0, n + K - N), np.minimum(n, K)
    lf = _logfact_fn(N.max())
    lc = lambda x, y: lf(x) - lf(y) - lf(x - y)
    mode = np.floor((n + 1.0) * (K + 1.0) / (N + 2.0)).astype(np.int64)

    def logpmf(x, i):
        return lc(K[i], x) + lc(N[i] - K[i], n[i] - x) - lc(N[i], n[i])

    up = a > mode                                          # tail above the mode: sum upward from a
    idx = np.where(up)[0]
    if idx.size:
        j = a[idx].copy(); term = np.ones(idx.size); tot = np.ones(idx.size)
        Ki, ni, Ni, hii = K[idx], n[idx], N[idx], hi[idx]
        act = np.arange(idx.size)
        while act.size:
            jj = j[act]
            r = (Ki[act] - jj) * (ni[act] - jj) / ((jj + 1.0) * (Ni[act] - Ki[act] - ni[act] + jj + 1.0))
            r = np.where(jj >= hii[act], 0.0, r)
            term[act] *= r; tot[act] += term[act]; j[act] += 1
            act = act[(term[act] > 1e-17 * tot[act]) & (j[act] < hii[act])]
        p[idx] = np.exp(logpmf(a[idx], idx)) * tot
    idx = np.where(~up & (a - 1 >= lo))[0]                 # otherwise p = 1 - P(X <= a-1): sum downward
    if idx.size:
        j = a[idx] - 1; term = np.ones(idx.size); tot = np.ones(idx.size)
        Ki, ni, Ni, loi = K[idx], n[idx], N[idx], lo[idx]
        act = np.arange(idx.size)
        while act.size:
            jj = j[act]
            r = jj * (Ni[act] - Ki[act] - ni[act] + jj) / ((Ki[act] - jj + 1.0) * (ni[act] - jj + 1.0))
            r = np.where(jj <= loi[act], 0.0, r)
            term[act] *= r; tot[act] += term[act]; j[act] -= 1
            act = act[(term[act] > 1e-17 * tot[act]) & (j[act] > loi[act])]
        p[idx] = 1.0 - np.exp(logpmf(a[idx] - 1, idx)) * tot
    return np.clip(p, 0.0, 1.0)


def odds_ratio(a, b, c, d):
    """Odds ratio with 0.5 added to every cell, and its 95% (Woolf) interval."""
    a, b, c, d = (np.asarray(v, dtype=float) + 0.5 for v in (a, b, c, d))
    o = a * d / (b * c)
    se = np.sqrt(1 / a + 1 / b + 1 / c + 1 / d)
    return o, np.exp(np.log(o) - 1.96 * se), np.exp(np.log(o) + 1.96 * se)


def bh_qvalues(p, n_family):
    """Benjamini-Hochberg q-values for p (one family) when the family has n_family tests in all.
    Tests left out of p all have larger p-values, so the ranks below them are unchanged."""
    p = np.asarray(p, dtype=float)
    if p.size == 0:
        return p
    order = np.argsort(p, kind='mergesort')
    ranks = np.arange(1, p.size + 1)
    q = p[order] * float(n_family) / ranks
    q = np.minimum.accumulate(q[::-1])[::-1]
    out = np.empty_like(q); out[order] = np.minimum(q, 1.0)
    return out


_MW_CACHE = {}


def _mw_exact_sf(n1, n2):
    """Exact null distribution of the Mann-Whitney U (no ties): sf[u] = P(U >= u)."""
    key = (n1, n2)
    if key not in _MW_CACHE:
        # w[j][u] = number of arrangements of i recent and j base values with U = u, built up over i
        prev = [np.zeros(1) for _ in range(n2 + 1)]
        for j in range(n2 + 1):
            prev[j][0] = 1.0                      # i = 0: one way, U = 0
        for i in range(1, n1 + 1):
            cur = [None] * (n2 + 1)
            cur[0] = np.zeros(1); cur[0][0] = 1.0
            for j in range(1, n2 + 1):
                a_ = np.zeros(i * j + 1)
                a_[j:j + len(prev[j])] += prev[j]  # largest value is recent: it beats all j base values
                a_[:len(cur[j - 1])] += cur[j - 1]  # largest value is base
                cur[j] = a_
            prev = cur
        cnt = prev[n2]
        _MW_CACHE[key] = np.cumsum(cnt[::-1])[::-1] / cnt.sum()
    return _MW_CACHE[key]


def mannwhitney_greater(X, Y, exact_max=40):
    """One-sided Mann-Whitney test, alternative: values in X tend to be larger than in Y.
    X: (rows, n1), Y: (rows, n2). Returns U and p per row. Exact p when a row has no ties and
    n1 + n2 <= exact_max; otherwise the normal approximation with tie and continuity correction
    (as scipy.stats.mannwhitneyu(..., alternative='greater'))."""
    X, Y = np.asarray(X, dtype=float), np.asarray(Y, dtype=float)
    n1, n2 = X.shape[1], Y.shape[1]
    U = (X[:, :, None] > Y[:, None, :]).sum(axis=(1, 2)) + 0.5 * (X[:, :, None] == Y[:, None, :]).sum(axis=(1, 2))
    Z = np.concatenate([X, Y], axis=1)
    n = n1 + n2
    t = (Z[:, :, None] == Z[:, None, :]).sum(axis=2)          # size of each value's tie group
    ties = (t ** 2 - 1).sum(axis=1)                           # = sum over groups of (t^3 - t)
    mu = n1 * n2 / 2.0
    var = n1 * n2 / 12.0 * ((n + 1) - ties / (n * (n - 1.0)))
    sd = np.sqrt(np.maximum(var, 0))
    z = np.where(sd > 0, (U - mu - 0.5) / np.where(sd > 0, sd, 1), -np.inf)
    erfc = np.frompyfunc(math.erfc, 1, 1)
    p = np.asarray(erfc(z / math.sqrt(2.0)), dtype=float) / 2.0
    exact = (ties == 0) & (n <= exact_max)
    if exact.any():
        sf = _mw_exact_sf(n1, n2)
        p[exact] = sf[U[exact].astype(int)]
    return U, np.clip(p, 0.0, 1.0)


# ---------------------------------------------------------------------------- Spark counts
def _windows(comparisons):
    """Distinct day windows (start, end) used by all comparisons; day 1 = the anchor day."""
    ws = []
    for cmp_ in comparisons:
        for w in (tuple(cmp_['recent']), tuple(cmp_['base'])):
            if w not in ws:
                ws.append(w)
    return ws


def _spark_counts(base, unit, metrics, wins, levels, a_start, a_end, spark):
    """Counts per seller x anchor day x window: n (total), f_<k> (flagged) for each flag metric,
    all_n (every seller), and for each peer group level ('p0', 'p1', ...) the same counts for the
    other sellers: <lvl>_n, <lvl>_m (other sellers), <lvl>_f_<k>.
    Counting by customers, the peer row leaves out every customer of this seller (disjoint rows)."""
    from pyspark.sql import functions as F
    flags = [m['name'] for m in metrics if m['kind'] == 'flag']
    W = spark.createDataFrame([(i, int(s), int(e)) for i, (s, e) in enumerate(wins)], 'w int, ws int, we int')
    gk = [gc for _, gc in levels]
    if unit == 'customer':
        r0 = base.groupBy(*gk, '_m', '_c', '_d').agg(*[F.max('_f_' + k).alias('_f_' + k) for k in flags])
    else:
        r0 = base.groupBy(*gk, '_m', '_d').agg(F.count(F.lit(1)).alias('_n'),
                                               *[F.sum('_f_' + k).alias('_f_' + k) for k in flags])
    lo = F.greatest(F.expr('date_add(_d, ws - 1)'), F.lit(a_start).cast('date'))
    hi = F.least(F.expr('date_add(_d, we - 1)'), F.lit(a_end).cast('date'))
    x = (r0.crossJoin(F.broadcast(W)).withColumn('_lo', lo).withColumn('_hi', hi)
         .where(F.col('_lo') <= F.col('_hi'))
         .withColumn('_t', F.explode(F.sequence('_lo', '_hi'))).drop('_lo', '_hi', 'ws', 'we', '_d'))
    key = gk + ['_m', '_t', 'w']
    cached = []
    if unit == 'customer':
        A = x.groupBy(*gk, '_m', '_c', '_t', 'w').agg(*[F.max('_f_' + k).alias('_f_' + k) for k in flags]).persist()
        cached.append(A)
        M = A.groupBy(*key).agg(F.count(F.lit(1)).alias('n'), *[F.sum('_f_' + k).alias('f_' + k) for k in flags])
        tot = A.select('_c', '_t', 'w').distinct().groupBy('_t', 'w').agg(F.count(F.lit(1)).alias('all_n'))
    else:
        M = x.groupBy(*key).agg(F.sum('_n').alias('n'), *[F.sum('_f_' + k).alias('f_' + k) for k in flags])
        tot = M.groupBy('_t', 'w').agg(F.sum('n').alias('all_n'))
    out = M.join(tot, ['_t', 'w'])
    for lvl, gc in levels:                                  # e.g. [('p0', '_g0'), ('p1', '_g1')]
        nm = M.groupBy(gc, '_t', 'w').agg(F.countDistinct('_m').alias('_gm'))
        if unit == 'customer':
            C = A.groupBy(gc, '_c', '_t', 'w').agg(*[F.max('_f_' + k).alias('_cf_' + k) for k in flags])
            G = C.groupBy(gc, '_t', 'w').agg(F.count(F.lit(1)).alias('_gn'),
                                             *[F.sum('_cf_' + k).alias('_gf_' + k) for k in flags])
            X = (A.select(gc, '_m', '_c', '_t', 'w').distinct().join(C, [gc, '_c', '_t', 'w'])
                 .groupBy(gc, '_m', '_t', 'w').agg(F.count(F.lit(1)).alias('_xn'),
                                                   *[F.sum('_cf_' + k).alias('_x_' + k) for k in flags]))
            P = (G.join(nm, [gc, '_t', 'w']).join(X, [gc, '_t', 'w'])
                 .select(gc, '_m', '_t', 'w', (F.col('_gn') - F.col('_xn')).alias(lvl + '_n'),
                         (F.col('_gm') - 1).alias(lvl + '_m'),
                         *[(F.col('_gf_' + k) - F.col('_x_' + k)).alias(lvl + '_f_' + k) for k in flags]))
        else:
            G = M.groupBy(gc, '_t', 'w').agg(F.sum('n').alias('_gn'), *[F.sum('f_' + k).alias('_gf_' + k) for k in flags])
            S = M.groupBy(gc, '_m', '_t', 'w').agg(F.sum('n').alias('_sn'), *[F.sum('f_' + k).alias('_s_' + k) for k in flags])
            P = (G.join(nm, [gc, '_t', 'w']).join(S, [gc, '_t', 'w'])
                 .select(gc, '_m', '_t', 'w', (F.col('_gn') - F.col('_sn')).alias(lvl + '_n'),
                         (F.col('_gm') - 1).alias(lvl + '_m'),
                         *[(F.col('_gf_' + k) - F.col('_s_' + k)).alias(lvl + '_f_' + k) for k in flags]))
        out = out.join(P, [gc, '_m', '_t', 'w'], 'left')
    return out, cached


def _spark_tests(counts, unit, metrics, comparisons, wins, levels, cfg, spark):
    """One row per seller x anchor x metric x comparison x test with the 2x2 table a, b, c, d.
    Tests: 'self', and 'peer:<cols>' for each peer group. One join for all comparisons, then one
    explode over metrics x tests (no unions)."""
    from pyspark.sql import functions as F
    flags = [m['name'] for m in metrics if m['kind'] == 'flag']
    lv = [(l, gc, lab) for (l, gc), lab in zip(levels, cfg['_peer_labels'])]
    cols = ['n', 'all_n'] + ['f_' + k for k in flags] + \
        [l + c for l, _, _ in lv for c in ['_n', '_m'] + ['_f_' + k for k in flags]]
    cmp_df = spark.createDataFrame([(c['name'], wins.index(tuple(c['recent'])), wins.index(tuple(c['base'])))
                                    for c in comparisons], 'comparison string, wr int, wb int')
    gk = [gc for _, gc, _ in lv]
    R = counts.join(F.broadcast(cmp_df), counts['w'] == cmp_df['wr']).select(
        *gk, '_m', '_t', 'comparison', 'wb', *[F.col(c).alias('r_' + c) for c in cols])
    B = counts.select(*gk, '_m', '_t', F.col('w').alias('wb'), *[F.col(c).alias('b_' + c) for c in cols])
    Ball = counts.select('_t', F.col('w').alias('wb'), F.col('all_n').alias('ball')).distinct()
    J = R.join(B, gk + ['_m', '_t', 'wb'], 'left').join(Ball, ['_t', 'wb'], 'left')
    z = lambda c: F.coalesce(F.col(c), F.lit(0)).cast('long')
    nr, nb = z('r_n'), z('b_n')
    none, nostr = F.lit(None).cast('long'), F.lit(None).cast('string')
    items = []           # (metric, test, a, b, c, d, flagged, other sellers, peer level or None)
    for m in metrics:
        k = m['name']
        if m['kind'] == 'flag':
            fr, fb = z('r_f_' + k), z('b_f_' + k)
            items.append((k, 'self', fr, nr - fr, fb, nb - fb, fr, none, None))
            for l, gc, lab in lv:
                pf, pn = z('r_' + l + '_f_' + k), z('r_' + l + '_n')
                items.append((k, 'peer:' + lab, fr, nr - fr, pf, pn - pf, fr, z('r_' + l + '_m'), (l, gc)))
        elif m['kind'] == 'volume':   # seller vs everyone else (self) or vs its peers, recent vs base
            items.append((k, 'self', nr, z('r_all_n') - nr, nb, z('ball') - nb, nr, none, None))
            for l, gc, lab in lv:
                items.append((k, 'peer:' + lab, nr, z('r_' + l + '_n'), nb, z('b_' + l + '_n'), nr,
                              z('r_' + l + '_m'), (l, gc)))
    structs = []
    for k, test, a, b, c, d, flagged, pm, lvl in items:
        gate = (nr >= cfg['min_total']) & (flagged >= cfg['min_flag'])
        if lvl:
            gate = gate & (pm >= cfg['min_peers']) & (z('r_' + lvl[0] + '_n') >= cfg['min_total'])
        structs.append(F.when(gate, F.struct(F.lit(k).alias('metric'), F.lit(test).alias('test'),
                                             a.alias('a'), b.alias('b'), c.alias('c'), d.alias('d'),
                                             pm.alias('peer_sellers'),
                                             (F.col(lvl[1]) if lvl else nostr).alias('peer_group'))))
    x = J.select(F.col('_t').alias('anchor'), F.col('_m').alias('merchant'),
                 'comparison', F.explode(F.array(*structs)).alias('s')).where(F.col('s').isNotNull())
    return x.select('anchor', 'merchant', 's.peer_group', 's.metric', 'comparison', F.lit(unit).alias('unit'),
                    's.test', 's.a', 's.b', 's.c', 's.d', 's.peer_sellers')


# ---------------------------------------------------------------------------- pandas steps
def _alerts(det, cooldown):
    """alert = a fired day at least `cooldown` days after this rule last alerted this seller."""
    det['alert'] = False
    f = det[det['fired']].sort_values('anchor')
    keys = ['merchant', 'metric', 'comparison', 'unit', 'test']
    keep = []
    for _, g in f.groupby(keys, sort=False):
        last = None
        for i, t in zip(g.index, g['anchor']):
            if last is None or (t - last).days >= cooldown:
                keep.append(i); last = t
    det.loc[keep, 'alert'] = True
    return det


def _expand(merch, start, offsets):
    """(seller, day) pairs: every start day shifted by every offset (days)."""
    merch, start = np.asarray(merch), pd.to_datetime(pd.Series(start)).values
    off = np.asarray(offsets, dtype='timedelta64[D]')
    out = pd.DataFrame({'merchant': np.repeat(merch, len(off)),
                        'day': np.repeat(start, len(off)) + np.tile(off, len(merch))})
    return out.drop_duplicates()


def _rate(L):
    o = L['obs_n'].sum()
    return (L['def_n'].sum() / o) if o else np.nan


def _summary(det, fam, n_days, comparisons, metrics, susp, loans, a_start, a_end, lift_days):
    keys = ['metric', 'comparison', 'unit', 'test']
    kind = {m['name']: m['kind'] for m in metrics}
    rec = {c['name']: tuple(c['recent']) for c in comparisons}
    tests = fam.groupby(keys)['n_tests'].sum()
    r4 = lambda v: _round(float(v), 4) if v == v else np.nan
    r2 = lambda v: _round(float(v), 2) if v == v else np.nan
    rows = []
    for k, g in det.groupby(keys, sort=False):
        fired, al = g[g['fired']], g[g['alert']]
        r = dict(zip(keys, k))
        r['rule_type'] = kind.get(k[0], 'flag')
        r.update(tests=int(tests.get(k, 0)), fired=len(fired), alerts=len(al),
                 alerts_per_day=_round(len(al) / _max(n_days, 1), 2), sellers_alerted=al['merchant'].nunique())
        if susp is not None:
            first = al.groupby('merchant')['anchor'].min()
            known = susp.dropna()
            hit = first.index.isin(known.index)
            r['precision'] = _round(hit.mean(), 3) if len(first) else np.nan
            target = known[(known >= a_start) & (known <= a_end)]
            caught = first.reindex(target.index).dropna()
            r['susp_in_range'] = len(target)
            r['recall'] = _round(len(caught) / len(target), 3) if len(target) else np.nan
            lead = (target.reindex(caught.index) - caught).dt.days
            r['recall_early'] = _round((lead >= 0).sum() / len(target), 3) if len(target) else np.nan
            r['median_lead_days'] = float(lead.median()) if len(lead) else np.nan
        if loans is not None:
            # forward: matured loans in the lift_days after each alert vs loans of sellers this rule never alerted
            fwd = _expand(al['merchant'], al['anchor'], range(1, lift_days + 1))
            fwd['_cov'] = True
            Lf = loans[(loans['day'] > a_start) & (loans['day'] <= a_end + pd.Timedelta(days=lift_days))]
            Lf = Lf.merge(fwd, on=['merchant', 'day'], how='left')
            after = Lf[Lf['_cov'].fillna(False).astype(bool)]
            never = Lf[~Lf['merchant'].isin(set(al['merchant']))]
            ra, ro = _rate(after), _rate(never)
            r.update(obs_after_alert=int(after['obs_n'].sum()), def_rate_after_alert=r4(ra),
                     def_rate_never_alerted=r4(ro), lift_after_alert=r2(ra / ro) if ro else np.nan)
            # in window: matured loans inside the recent window of fired days vs all other loans (looks back)
            s_, e_ = rec[k[1]]
            cov = _expand(fired['merchant'], fired['anchor'], [-(b_ - 1) for b_ in range(s_, e_ + 1)])
            cov['_cov'] = True
            Lw = loans[(loans['day'] >= a_start) & (loans['day'] <= a_end)].merge(cov, on=['merchant', 'day'], how='left')
            inn = Lw['_cov'].fillna(False).astype(bool)
            ra, ro = _rate(Lw[inn]), _rate(Lw[~inn])
            r.update(obs_in_window=int(Lw.loc[inn, 'obs_n'].sum()), def_rate_in_window=r4(ra),
                     def_rate_outside=r4(ro), lift_in_window=r2(ra / ro) if ro else np.nan)
        rows.append(r)
    done = {tuple(r[c] for c in keys) for r in rows}
    for k in tests.index:                               # rules that never had a candidate row
        if tuple(k) not in done:
            rows.append(dict(zip(keys, k), rule_type=kind.get(k[0], 'flag'), tests=int(tests[k]), fired=0, alerts=0,
                             alerts_per_day=0.0, sellers_alerted=0))
    out = pd.DataFrame(rows)
    sort = [c for c in ['precision', 'recall', 'alerts'] if c in out.columns]
    return out.sort_values(sort, ascending=False, na_position='last').reset_index(drop=True)


def _intervals(det, comparisons):
    """Seller day ranges covered by the recent window of each fired day / alert, per rule, with
    overlapping or touching ranges merged (each transaction then falls in at most one range)."""
    keys = ['metric', 'comparison', 'unit', 'test']
    rec = {c['name']: tuple(c['recent']) for c in comparisons}
    rules = det[keys].drop_duplicates().reset_index(drop=True)
    rules['rid'] = np.arange(len(rules))
    parts = []
    for basis, col in [('fired', 'fired'), ('alert', 'alert')]:
        ev = det[det[col]].merge(rules, on=keys)
        if not len(ev):
            continue
        s_ = ev['comparison'].map(lambda c: rec[c][0]).values
        e_ = ev['comparison'].map(lambda c: rec[c][1]).values
        parts.append(pd.DataFrame({'rid': ev['rid'].values, 'basis': basis, 'merchant': ev['merchant'].values,
                                   'start': ev['anchor'].values - pd.to_timedelta(e_ - 1, unit='D'),
                                   'end': ev['anchor'].values - pd.to_timedelta(s_ - 1, unit='D')}))
    if not parts:
        return rules, pd.DataFrame(columns=['rid', 'basis', 'merchant', 'start', 'end'])
    iv = pd.concat(parts, ignore_index=True).sort_values(['rid', 'basis', 'merchant', 'start'])
    g = ['rid', 'basis', 'merchant']
    prev_end = iv.groupby(g)['end'].transform(lambda x: x.cummax().shift())
    new = prev_end.isna() | (iv['start'] > prev_end + pd.Timedelta(days=1))
    iv['_k'] = new.cumsum()
    iv = iv.groupby(g + ['_k'], as_index=False).agg(start=('start', 'min'), end=('end', 'max')).drop(columns='_k')
    return rules, iv


def _money_tests(daily, metric, comparisons, cfg, start, a_s, a_e):
    """Money surge: one-sided Mann-Whitney on the seller's DAILY total amount, recent days vs base
    days (days without sales count as 0). Self only; comparisons with a recent window under 3 days
    are skipped. Returns candidate rows (U above its mean) and the family sizes per anchor."""
    sellers = np.array(sorted(daily['merchant'].unique()))
    n_days = (a_e - start).days + 1
    si = pd.Index(sellers).get_indexer(daily['merchant'])
    di = (daily['day'] - start).dt.days.values
    ok_ = (di >= 0) & (di < n_days)
    A = np.zeros((len(sellers), n_days)); N = np.zeros((len(sellers), n_days))
    np.add.at(A, (si[ok_], di[ok_]), daily['amt'].values[ok_].astype(float))
    np.add.at(N, (si[ok_], di[ok_]), daily['n'].values[ok_].astype(float))
    rows, fam = [], []
    for c in comparisons:
        (rs, re_), (bs, be) = c['recent'], c['base']
        if re_ - rs + 1 < 3:
            continue
        for t in pd.date_range(a_s, a_e):
            i = (t - start).days
            r0, r1, b0, b1 = i - re_ + 1, i - rs + 1, i - be + 1, i - bs + 1
            if b0 < 0:
                continue
            gate = N[:, r0:r1 + 1].sum(axis=1) >= cfg['min_total']
            fam.append((t, metric, c['name'], int(gate.sum())))
            if not gate.any():
                continue
            X, Y = A[gate, r0:r1 + 1], A[gate, b0:b1 + 1]
            U, p = mannwhitney_greater(X, Y)
            up = U > X.shape[1] * Y.shape[1] / 2.0
            if not up.any():
                continue
            X, Y, U, p = X[up], Y[up], U[up], p[up]
            rows.append(pd.DataFrame({
                'anchor': t, 'merchant': sellers[gate][up], 'peer_group': None, 'metric': metric,
                'comparison': c['name'], 'unit': 'amount', 'test': 'self',
                'a': np.round(X.sum(axis=1)).astype(np.int64), 'b': np.round(Y.sum(axis=1)).astype(np.int64),
                'c': X.shape[1], 'd': Y.shape[1], 'peer_sellers': np.nan,
                'share_recent': X.mean(axis=1), 'share_ref': Y.mean(axis=1), 'p': p}))
    det = pd.concat(rows, ignore_index=True) if rows else pd.DataFrame(
        columns=['anchor', 'merchant', 'peer_group', 'metric', 'comparison', 'unit', 'test', 'a', 'b', 'c', 'd',
                 'peer_sellers', 'share_recent', 'share_ref', 'p'])
    fam = pd.DataFrame(fam, columns=['anchor', 'metric', 'comparison', 'n_tests'])
    fam['unit'], fam['test'] = 'amount', 'self'
    return det, fam[fam['n_tests'] > 0]


RAW_EDGES = [0.0, 0.35, 0.55, 1.0, 1.96]     # raw z = 0.5 ln(MP / ref): about 2x, 3x, 7x, 50x
STD_EDGES = [0.0, 1.0, 2.0, 3.0]             # standardised z: spreads above the typical seller


def _band_labels(edges, unit=''):
    e = [('%g' % x) for x in edges]
    return ['below ' + e[0]] + [e[i] + '-' + e[i + 1] for i in range(len(e) - 1)] + [e[-1] + '+']


def _ratio_z(cd, codes, values, labels, metric, comparisons, cfg, start, a_s, a_e):
    """Ratio Z (the picture's approach), per seller and anchor day.

    MP = the seller's average daily amount in the recent window; the reference is its average
    daily amount in the base window (self) or the average MP of the OTHER active sellers in its
    peer group (peer). r = (MP - ref) / (MP + ref), clipped to +-0.999, z = 0.5 ln((1+r)/(1-r)).
    and:<group> = the smaller of z_self and z_peer, or:<group> = the larger, when both exist. Standardised z =
    (z - median) / (1.4826 MAD) across the sellers tested that day (per group value for peer,
    and, or), when at least 5 sellers and MAD > 0. Not a test: no p, q, fired or alert.

    cd: one row per seller x day x client (n, s, o, x, amt). Returns (detail rows with z_raw > 0,
    z_bands table)."""
    raw_e = [float(x) for x in metric.get('raw_edges') or RAW_EDGES]
    std_e = [float(x) for x in metric.get('std_edges') or STD_EDGES]
    sellers = codes.index.values
    S, D = len(sellers), (a_e - start).days + 1
    si = codes.index.get_indexer(cd['merchant']); di = (cd['day'] - start).dt.days.values
    A = np.zeros((S, D)); N = np.zeros((S, D))
    np.add.at(A, (si, di), cd['amt'].values.astype(float)); np.add.at(N, (si, di), cd['n'].values.astype(float))
    cA = np.concatenate([np.zeros((S, 1)), np.cumsum(A, axis=1)], axis=1)
    cN = np.concatenate([np.zeros((S, 1)), np.cumsum(N, axis=1)], axis=1)
    ia, ie = (a_s - start).days, (a_e - start).days
    zf = lambda x, ref: np.arctanh(np.clip(np.where(x + ref > 0, (x - ref) / np.where(x + ref > 0, x + ref, 1), 0.0),
                                           -0.999, 0.999))
    in_rng = (di >= ia) & (di <= ie)
    cdr = cd[in_rng]; rsi, rdi = si[in_rng], di[in_rng]
    cl_codes, cl_uni = pd.factorize(cdr['client'])
    NC = _max(len(cl_uni), 1)
    det_rows, band_rows = [], []
    for c in comparisons:
        (rs, re_), (bs, be) = c['recent'], c['base']
        idx = np.arange(_max(ia, be - 1), ie + 1)
        if not len(idx):
            continue
        ws = lambda C, lo, hi: C[:, idx - lo + 2] - C[:, idx - hi + 1]
        MP = ws(cA, rs, re_) / (re_ - rs + 1); RP = ws(cA, bs, be) / (be - bs + 1); NR = ws(cN, rs, re_)
        G = NR >= cfg['min_total']
        rules = [('self', np.where(G, zf(MP, RP), np.nan), np.where(G, RP, np.nan), None)]
        active = MP > 0
        for gi, lab in enumerate(labels):
            cg = codes['g%d' % gi].values
            ng = _max(cg.max() + 1, 1)
            T = len(idx)
            gs = np.zeros((ng, T)); gc = np.zeros((ng, T))
            rows_ = np.repeat(cg[:, None], T, axis=1); cols_ = np.repeat(np.arange(T)[None, :], S, axis=0)
            np.add.at(gs, (rows_, cols_), MP * active); np.add.at(gc, (rows_, cols_), active.astype(float))
            oc = gc[cg] - active; osum = gs[cg] - MP * active
            avg = np.where(oc > 0, osum / np.where(oc > 0, oc, 1), np.nan)
            ok = G & (oc >= cfg['min_peers'])
            zp = np.where(ok, zf(MP, np.nan_to_num(avg)), np.nan)
            zs = rules[0][1]
            both = ok & ~np.isnan(zs)
            rules += [('peer:' + lab, zp, np.where(ok, avg, np.nan), gi),
                      ('and:' + lab, np.where(both, np.fmin(zs, zp), np.nan), np.full_like(zp, np.nan), gi),
                      ('or:' + lab, np.where(both, np.fmax(zs, zp), np.nan), np.full_like(zp, np.nan), gi)]
        for test, Z, REF, gi in rules:
            tested = ~np.isnan(Z)
            # standardised z: per anchor (and group value) across tested sellers
            s_i, t_i = np.nonzero(tested)
            grp = codes['g%d' % gi].values[s_i] if gi is not None else np.zeros(len(s_i), dtype=int)
            L = pd.DataFrame({'t': t_i, 'g': grp, 'z': Z[s_i, t_i]})
            gb = L.groupby(['t', 'g'])['z']
            med = gb.transform('median'); cnt = gb.transform('size')
            mad = (L['z'] - med).abs().groupby([L['t'], L['g']]).transform('median') * 1.4826
            zstd = np.where((cnt >= 5) & (mad > 0), (L['z'] - med) / mad.where(mad > 0, 1), np.nan)
            ZS = np.full(Z.shape, np.nan); ZS[s_i, t_i] = zstd
            # detail rows: leaning up (z_raw > 0)
            up = L['z'].values > 0
            if up.any():
                su, tu = s_i[up], t_i[up]
                anch = start + pd.to_timedelta(idx[tu], unit='D')
                ref_recent = test.startswith('peer')
                det_rows.append(pd.DataFrame({
                    'anchor': anch, 'merchant': sellers[su],
                    'peer_group': (values[gi][codes['g%d' % gi].values[su]] if gi is not None else None),
                    'metric': metric['name'], 'comparison': c['name'], 'unit': 'ratio', 'test': test,
                    'z_raw': Z[su, tu], 'z_std': ZS[su, tu], 'mp_per_day': MP[su, tu], 'ref_per_day': REF[su, tu],
                    'recent_start': anch - pd.Timedelta(days=re_ - 1), 'recent_end': anch - pd.Timedelta(days=rs - 1),
                    'ref_start': anch - pd.Timedelta(days=(re_ if ref_recent else be) - 1),
                    'ref_end': anch - pd.Timedelta(days=(rs if ref_recent else bs) - 1)}))
            # coverage: each seller-day takes the largest z of the anchors whose recent window covers it
            for scale, M, edges in [('raw', Z, raw_e), ('std', ZS, std_e)]:
                ZD = np.full((S, D), np.nan); ZD[:, idx] = M
                TD = np.zeros((S, D), dtype=bool); TD[:, idx] = tested
                cov = np.full((S, D), np.nan); tcov = np.zeros((S, D), dtype=bool)
                for k in range(rs - 1, re_):
                    if k >= D:
                        break
                    sh = np.full((S, D), np.nan); sh[:, :D - k] = ZD[:, k:]
                    cov = np.fmax(cov, sh)
                    tb = np.zeros((S, D), dtype=bool); tb[:, :D - k] = TD[:, k:]
                    tcov |= tb
                nb = len(edges) + 1
                band = np.where(~tcov, nb + 1, np.where(np.isnan(cov), nb, 0))
                okb = ~np.isnan(cov)
                band[okb] = np.searchsorted(np.asarray(edges), cov[okb], side='right')
                b = band[rsi, rdi]
                K = nb + 2
                cnt_ = lambda w: np.bincount(b, weights=w, minlength=K)
                def ncl(mask):
                    key = b[mask].astype(np.int64) * NC + cl_codes[mask]
                    u = np.unique(key)
                    return np.bincount((u // NC).astype(int), minlength=K)
                tx = cnt_(cdr['n'].values.astype(float)); sx = cnt_(cdr['s'].values.astype(float))
                ox = cnt_(cdr['o'].values.astype(float)); xx = cnt_(cdr['x'].values.astype(float))
                ax = cnt_(cdr['amt'].values.astype(float))
                allm = np.ones(len(b), dtype=bool)
                c_all, c_s = ncl(allm), ncl(cdr['s'].values > 0)
                c_o, c_x = ncl(cdr['o'].values > 0), ncl(cdr['x'].values > 0)
                own = M[tested]
                sb = np.where(np.isnan(own), nb, np.searchsorted(np.asarray(edges), np.nan_to_num(own), side='right'))
                sd_ = np.bincount(sb, minlength=K)
                names = _band_labels(edges) + ['n/a (under 5 sellers or no spread)', 'not tested']
                for k_ in range(K):
                    if scale == 'raw' and k_ == nb:
                        continue
                    band_rows.append({'metric': metric['name'], 'comparison': c['name'], 'test': test, 'scale': scale,
                                      'band_order': k_, 'band': names[k_],
                                      'seller_days': int(sd_[k_]) if k_ <= nb else 0,
                                      'txn': int(tx[k_]), 'client': int(c_all[k_]),
                                      'susp_txn': int(sx[k_]), 'susp_client': int(c_s[k_]),
                                      'obs_txn': int(ox[k_]), 'obs_client': int(c_o[k_]),
                                      'def_txn': int(xx[k_]), 'def_client': int(c_x[k_]),
                                      'amount': _round(float(ax[k_]), 2)})
    det = pd.concat(det_rows, ignore_index=True) if det_rows else pd.DataFrame()
    zb = pd.DataFrame(band_rows)
    if len(zb):
        dv = lambda a, b: (zb[a] / zb[b].where(zb[b] > 0)).round(4)
        zb['susp_rate_txn'], zb['susp_rate_client'] = dv('susp_txn', 'txn'), dv('susp_client', 'client')
        zb['def_rate_txn'], zb['def_rate_client'] = dv('def_txn', 'obs_txn'), dv('def_client', 'obs_client')
    return det, zb


# ---------------------------------------------------------------------------- main
def run_fisher_backtest(df, config, spark=None):
    """Rolling backtest of Fisher-test triggers. Every day in the anchor range plays 'today'.

    Returns a dict: ok, detail (pandas: one row per tested seller x day x rule), summary
    (pandas: one row per rule), outcomes (pandas: per rule, transactions in the recent window of
    fired days / alerts vs the rest: suspicious, default and observed, by transaction and by
    client), failed_step and error when it stopped."""
    from pyspark.sql import functions as F
    cfg = dict(DEFAULTS); cfg.update(config or {})
    spark = spark or df.sparkSession
    comparisons = cfg['comparisons']
    if cfg.get('peer_cols') and not cfg['peer_groups']:          # older settings: one combined group
        cfg['peer_groups'] = [list(cfg['peer_cols'])]
    groups = [list(g) for g in cfg['peer_groups'] if g]
    levels = [('p%d' % i, '_g%d' % i) for i in range(len(groups))]
    cfg['_peer_labels'] = ['+'.join(g) for g in groups]
    user_metrics = cfg['metrics']
    # relative amount: one flag per peer group (or one over all sellers when there are no peer groups)
    metrics, rel = [], []
    for m in user_metrics:
        if m['kind'] == 'rel_amount':
            for gi, g in enumerate(groups or [[]]):
                name = m['name'] + '_' + ('_'.join(g) if g else 'all')
                metrics.append({'name': name, 'kind': 'flag', 'rel': (gi if g else None, float(m.get('level', 0.9)))})
                rel.append(name)
        elif m['kind'] in ('flag', 'volume'):
            metrics.append(m)
    money = [m['name'] for m in user_metrics if m['kind'] == 'money']
    ratio = [m for m in user_metrics if m['kind'] == 'ratio_z']
    kinds = {m['name']: ('amount' if m['kind'] == 'money' else 'volume' if m['kind'] == 'volume' else 'flag')
             for m in metrics + [m for m in user_metrics if m['kind'] == 'money']}
    units = list(cfg['units'])
    steps = ['check_inputs', 'anchor_range'] + (['amount_thresholds'] if rel else []) + \
            ['spark_tests_' + u for u in units] + (['money_tests'] if money else []) + \
            ['fisher_and_q', 'alerts'] + (['ratio_z'] if ratio else []) + \
            ['spark_labels', 'spark_row_totals', 'spark_outcomes', 'summary']
    res = {'ok': False, 'detail': None, 'summary': None, 'outcomes': None, 'z_bands': None, 'failed': []}
    st = {}
    t0 = time.time()

    def step(i, name, fn):
        _log(f"[{i}/{len(steps)}] {name} ...")
        t = time.time()
        out = fn()
        _log(f"      done in {time.time() - t:.1f}s")
        return out

    def check():
        if cfg.get('peer_fallback_cols'):
            raise ValueError('peer_fallback_cols was replaced by peer_groups: list each group to test')
        need = [cfg['date_col'], cfg['merchant_col'], cfg['customer_col']] + [c for g in groups for c in g]
        if rel or money or ratio:
            if not cfg['amount_col']:
                raise ValueError('relative amount, money surge and ratio z metrics need amount_col')
            need.append(cfg['amount_col'])
        miss = [c for c in dict.fromkeys(need) if c not in df.columns]
        if miss:
            raise ValueError(f"columns not in df: {', '.join(miss)}")
        if cfg['bh_scope'] not in ('rule', 'day'):
            raise ValueError("bh_scope must be 'rule' or 'day'")
        names = [m['name'] for m in user_metrics] + rel
        if len(set(names)) != len(names):
            raise ValueError('metric names must be unique (relative amount adds <name>_<group> metrics)')
        for m in user_metrics:
            if m['kind'] not in ('flag', 'volume', 'rel_amount', 'money', 'ratio_z'):
                raise ValueError(f"metric {m['name']}: unknown kind {m['kind']}")
            if m['kind'] == 'rel_amount' and not (0 < float(m.get('level', 0.9)) < 1):
                raise ValueError(f"metric {m['name']}: level must be between 0 and 1, e.g. 0.9")
        for cmp_ in comparisons:
            (s1, e1), (s2, e2) = cmp_['recent'], cmp_['base']
            if not (1 <= s1 <= e1 and 1 <= s2 <= e2):
                raise ValueError(f"comparison {cmp_['name']}: windows need 1 <= start <= end")
        exprs = [m['expr'] for m in metrics if m['kind'] == 'flag' and 'rel' not in m]
        if cfg['susp_cond']:
            exprs.append(cfg['susp_cond'])
        for c in [cfg['susp_date_col'], cfg['def_col'], cfg['obs_col']]:
            if c and c not in df.columns:
                raise ValueError(f"column not in df: {c}")
        for e in exprs:
            df.limit(0).select(F.expr(e)).schema   # raises if the SQL condition does not parse

    def grp(cs):
        return F.concat_ws(' | ', *[F.coalesce(F.col(c).cast('string'), F.lit('(null)')) for c in cs]) \
            if cs else F.lit('all')

    def build_base(thr=None):
        """One row per transaction: date, seller, customer, peer group keys and 0/1 flags."""
        x = df.select(F.to_date(F.col(cfg['date_col'])).alias('_d'),
                      F.col(cfg['merchant_col']).cast('string').alias('_m'),
                      F.col(cfg['customer_col']).cast('string').alias('_c'),
                      *[grp(g).alias('_g%d' % i) for i, g in enumerate(groups)],
                      *([F.col(cfg['amount_col']).cast('double').alias('_amt')] if rel else []),
                      *[F.when(F.expr(m['expr']), 1).otherwise(0).alias('_f_' + m['name'])
                        for m in metrics if m['kind'] == 'flag' and 'rel' not in m]
                      ).where(F.col('_d').isNotNull() & F.col('_m').isNotNull())
        for m in metrics:
            if 'rel' in m:
                gi, _ = m['rel']
                key = '_g%d' % gi if gi is not None else None
                T = thr[m['name']]
                if key:
                    x = x.join(F.broadcast(T.withColumnRenamed('_key', key)), key, 'left')
                else:
                    x = x.crossJoin(F.broadcast(T.drop('_key')))
                x = x.withColumn('_f_' + m['name'], F.when(F.col('_amt') > F.col('_thr'), 1).otherwise(0)).drop('_thr')
        st['base'] = x.drop('_amt') if rel else x

    def anchors():
        d = F.to_date(F.col(cfg['date_col']))
        r = df.where(d.isNotNull() & F.col(cfg['merchant_col']).isNotNull()).agg(
            F.min(d).alias('lo'), F.max(d).alias('hi')).collect()[0]
        if r['lo'] is None:
            raise ValueError('df has no rows with a date and a seller')
        lo, hi = pd.Timestamp(r['lo']), pd.Timestamp(r['hi'])
        if cfg['skip_last_day']:
            hi -= pd.Timedelta(days=1)
        max_back = _max(_max(c['recent'][1], c['base'][1]) for c in comparisons)
        a_s = pd.Timestamp(cfg['anchor_start']) if cfg['anchor_start'] else lo + pd.Timedelta(days=max_back - 1)
        a_e = _min(pd.Timestamp(cfg['anchor_end']), hi) if cfg['anchor_end'] else hi
        if a_s > a_e:
            raise ValueError(f"no anchor days: data {lo.date()} to {hi.date()}, the longest window needs "
                             f"{max_back} days, so anchors would start {a_s.date()}")
        st['a_s'], st['a_e'], st['max_back'] = a_s, a_e, max_back
        st['n_days'] = (a_e - a_s).days + 1
        st['lo'] = lo
        _log(f"      data {lo.date()} to {hi.date()}; anchors {a_s.date()} to {a_e.date()} ({st['n_days']} days)")
        if not rel:
            build_base()

    def thresholds():
        """Relative amount: the amount percentile per peer group value, from data BEFORE the first anchor
        day only (no look-ahead). A transaction is flagged when its amount is above it."""
        d = F.to_date(F.col(cfg['date_col']))
        train = df.where(d.isNotNull() & (d < F.lit(str(st['a_s'].date())).cast('date')))
        if not train.limit(1).count():
            raise ValueError('relative amount needs data before the first anchor day: set anchor_start later')
        amt = F.col(cfg['amount_col']).cast('double')
        thr = {}
        for m in metrics:
            if 'rel' in m:
                gi, level = m['rel']
                if gi is None:
                    T = train.agg(F.expr(f'percentile_approx({cfg["amount_col"]}, {level}, 10000)').cast('double').alias('_thr'))
                    T = T.withColumn('_key', F.lit('all'))
                else:
                    T = train.select(grp(groups[gi]).alias('_key'), amt.alias('_a')).groupBy('_key').agg(
                        F.expr(f'percentile_approx(_a, {level}, 10000)').alias('_thr'))
                thr[m['name']] = T.persist()
                _log(f"      {m['name']}: {T.count():,} group thresholds (p{level * 100:g})")
        st['thr'] = thr
        build_base(thr)

    def tests_for(unit):
        def run():
            wins = _windows(comparisons)
            cnt, cached = _spark_counts(st['base'], unit, metrics, wins, levels, str(st['a_s'].date()), str(st['a_e'].date()), spark)
            cnt = cnt.persist()
            t = _spark_tests(cnt, unit, metrics, comparisons, wins, levels, cfg, spark).persist()
            fam = t.groupBy('anchor', 'metric', 'comparison', 'unit', 'test').agg(F.count(F.lit(1)).alias('n_tests')).toPandas()
            # only rows leaning the suspicious way (a*d > b*c) can reach a small p; the rest stay in the family count
            cand = t.where(F.col('a') * F.col('d') > F.col('b') * F.col('c'))
            n = cand.count()
            if n + _sum(len(v) for v in st.get('det', [])) > cfg['max_rows']:
                raise ValueError(f"{n:,} candidate rows for unit={unit} is over max_rows={cfg['max_rows']:,}. "
                                 f"Raise min_total/min_flag, shorten the anchor range, or raise max_rows")
            pdf = cand.toPandas()
            t.unpersist(); cnt.unpersist()
            for c_ in cached:
                c_.unpersist()
            st.setdefault('det', []).append(pdf); st.setdefault('fam', []).append(fam)
            _log(f"      {int(fam['n_tests'].sum()):,} tests, {n:,} leaning up (kept)")
        return run

    def money_step():
        d = F.to_date(F.col(cfg['date_col']))
        start = st['a_s'] - pd.Timedelta(days=st['max_back'] - 1)
        daily = (df.where(d.between(str(start.date()), str(st['a_e'].date())) & F.col(cfg['merchant_col']).isNotNull())
                 .groupBy(F.col(cfg['merchant_col']).cast('string').alias('merchant'), d.alias('day'))
                 .agg(F.sum(F.col(cfg['amount_col']).cast('double')).alias('amt'), F.count(F.lit(1)).alias('n'))
                 .toPandas())
        daily['day'] = pd.to_datetime(daily['day']); daily['amt'] = daily['amt'].fillna(0.0)
        for name in money:
            det_m, fam_m = _money_tests(daily, name, comparisons, cfg, start, st['a_s'], st['a_e'])
            st.setdefault('det', []).append(det_m); st.setdefault('fam', []).append(fam_m)
            _log(f"      {name}: {int(fam_m['n_tests'].sum()):,} tests, {len(det_m):,} leaning up (kept)")

    def fisher():
        det = pd.concat(st['det'], ignore_index=True)
        fam = pd.concat(st['fam'], ignore_index=True)
        det['anchor'] = pd.to_datetime(det['anchor']); fam['anchor'] = pd.to_datetime(fam['anchor'])
        for c in 'abcd':
            det[c] = det[c].astype(np.int64)
        for c in ['share_recent', 'share_ref', 'p']:
            if c not in det.columns:
                det[c] = np.nan
        fi = (det['unit'] != 'amount').values                     # Fisher rows; 'amount' = money surge rows
        A_, B_, C_, D_ = (det.loc[fi, c].values for c in 'abcd')
        det.loc[fi, 'share_recent'] = A_ / np.where(A_ + B_ > 0, A_ + B_, np.nan)
        det.loc[fi, 'share_ref'] = C_ / np.where(C_ + D_ > 0, C_ + D_, np.nan)
        det['odds_ratio'] = det['or_lo'] = det['or_hi'] = np.nan
        if fi.any():
            o, lo_, hi_ = odds_ratio(A_, B_, C_, D_)
            det.loc[fi, 'odds_ratio'], det.loc[fi, 'or_lo'], det.loc[fi, 'or_hi'] = o, lo_, hi_
            det.loc[fi, 'p'] = fisher_greater(A_, B_, C_, D_)
        det['p'] = det['p'].astype(float)
        # the exact days behind a, b (recent) and c, d (ref), to filter df back to the same rows
        rec = {c['name']: c['recent'] for c in comparisons}; bas = {c['name']: c['base'] for c in comparisons}
        day = lambda col, back: det['anchor'] - pd.to_timedelta(det['comparison'].map(
            lambda c: (rec if col == 'r' else bas)[c][back]) - 1, unit='D')
        det['recent_start'], det['recent_end'] = day('r', 1), day('r', 0)
        peer_flag = det['test'].str.startswith('peer') & (det['metric'].map(kinds) == 'flag')
        det['ref_start'] = day('b', 1).where(~peer_flag, det['recent_start'])
        det['ref_end'] = day('b', 0).where(~peer_flag, det['recent_end'])
        keys = ['anchor'] if cfg['bh_scope'] == 'day' else ['anchor', 'metric', 'comparison', 'unit', 'test']
        det = det.merge(fam.groupby(keys, as_index=False)['n_tests'].sum(), on=keys, how='left')
        det['q'] = np.nan
        for _, idx in det.groupby(keys).groups.items():
            det.loc[idx, 'q'] = bh_qvalues(det.loc[idx, 'p'].values, det.loc[idx[0], 'n_tests'])
        det['fired'] = (det['q'] <= cfg['q_max']) & ((det['odds_ratio'] >= cfg['or_min']) | (det['unit'] == 'amount'))
        st['detail'], st['fam'] = det, fam
        _log(f"      {int(det['fired'].sum()):,} fired")

    def alerts():
        st['detail'] = _alerts(st['detail'], int(cfg['cooldown']))
        _log(f"      {int(st['detail']['alert'].sum()):,} alerts after the {cfg['cooldown']}-day cooldown")

    def ratio_step():
        """Ratio Z rules (the picture's approach): z per seller-day, detail rows and z_bands."""
        d = F.to_date(F.col(cfg['date_col']))
        start = st['a_s'] - pd.Timedelta(days=st['max_back'] - 1)
        one = lambda c: F.when(c, 1).otherwise(0)
        has_s, has_d = bool(cfg['susp_cond']), bool(cfg['def_col'] and cfg['obs_col'])
        obs = (F.col(cfg['obs_col']).cast('int') == 1) if has_d else F.lit(False)
        src = df.where(d.between(str(start.date()), str(st['a_e'].date())) & F.col(cfg['merchant_col']).isNotNull())
        cd = (src.groupBy(F.col(cfg['merchant_col']).cast('string').alias('merchant'), d.alias('day'),
                          F.col(cfg['customer_col']).cast('string').alias('client'))
              .agg(F.count(F.lit(1)).alias('n'),
                   F.sum(one(F.expr(cfg['susp_cond'])) if has_s else F.lit(0)).alias('s'),
                   F.sum(one(obs)).alias('o'),
                   F.sum(one(obs & (F.col(cfg['def_col']).cast('int') == 1)) if has_d else F.lit(0)).alias('x'),
                   F.sum(F.col(cfg['amount_col']).cast('double')).alias('amt')).toPandas())
        cd['day'] = pd.to_datetime(cd['day']); cd['amt'] = cd['amt'].fillna(0.0)
        _log(f"      {len(cd):,} seller-day-client rows")
        sellers = sorted(cd['merchant'].unique())
        if groups:
            gm = src.groupBy(F.col(cfg['merchant_col']).cast('string').alias('merchant')).agg(
                *[F.first(grp(g), ignorenulls=True).alias('g%d' % i) for i, g in enumerate(groups)]).toPandas()
            gm = gm.set_index('merchant').reindex(sellers)
        else:
            gm = pd.DataFrame(index=pd.Index(sellers, name='merchant'))
        codes = pd.DataFrame(index=gm.index); values = []
        for i in range(len(groups)):
            cc, uu = pd.factorize(gm['g%d' % i].fillna('(null)'))
            codes['g%d' % i] = cc; values.append(np.asarray(uu, dtype=object))
        dets, zbs = [], []
        for m in ratio:
            det_r, zb = _ratio_z(cd, codes, values, cfg['_peer_labels'], m, comparisons, cfg, start, st['a_s'], st['a_e'])
            dets.append(det_r); zbs.append(zb)
            _log(f"      {m['name']}: {len(det_r):,} seller-days with z > 0, {len(zb):,} band rows")
        add = pd.concat(dets, ignore_index=True) if dets else pd.DataFrame()
        if len(add):
            if len(add) + len(st['detail']) > cfg['max_rows'] * 2:
                raise ValueError(f"{len(add):,} ratio z rows: too many for pandas. Shorten the anchor range "
                                 f"or raise min_total")
            det = pd.concat([st['detail'], add], ignore_index=True)
            for c_ in 'abcd':
                det[c_] = det[c_].astype('Int64')
            det['fired'] = det['fired'].fillna(False).astype(bool); det['alert'] = det['alert'].fillna(False).astype(bool)
            st['detail'] = det
        st['z_bands'] = pd.concat(zbs, ignore_index=True).sort_values(
            ['metric', 'comparison', 'test', 'scale', 'band_order']).reset_index(drop=True)

    def labels():
        st['susp'] = st['loans'] = None
        m = F.col(cfg['merchant_col']).cast('string')
        if cfg['susp_cond']:
            dt = F.to_date(F.col(cfg['susp_date_col'])) if cfg['susp_date_col'] else F.to_date(F.col(cfg['date_col']))
            s = (df.where(F.expr(cfg['susp_cond'])).groupBy(m.alias('merchant'))
                 .agg(F.min(dt).alias('susp_date')).toPandas())
            st['susp'] = pd.to_datetime(s.set_index('merchant')['susp_date'])
            _log(f"      {len(s):,} suspicious sellers")
        if cfg['def_col'] and cfg['obs_col']:
            d = F.to_date(F.col(cfg['date_col']))
            l = (df.where(F.col(cfg['obs_col']).cast('int') == 1)
                 .where(d >= F.lit(str((st['a_s'] - pd.Timedelta(days=st['max_back'])).date())).cast('date'))
                 .groupBy(m.alias('merchant'), d.alias('day'))
                 .agg(F.count(F.lit(1)).alias('obs_n'), F.sum(F.col(cfg['def_col']).cast('int')).alias('def_n')).toPandas())
            l['day'] = pd.to_datetime(l['day'])
            st['loans'] = l
            _log(f"      {int(l['obs_n'].sum()):,} observed loans (from the first window day)")

    def row_totals():
        """Per detail row: the seller's own transactions in the recent window (recent_start..recent_end):
        txn_cnt, susp_cnt, def_cnt (defaulted and observed), obs_cnt, loan_amt. One Spark pass to daily
        totals per seller, then cumulative sums in pandas."""
        det = st['detail']
        has_s, has_d, has_a = bool(cfg['susp_cond']), bool(cfg['def_col'] and cfg['obs_col']), bool(cfg['amount_col'])
        start = st['a_s'] - pd.Timedelta(days=st['max_back'] - 1)
        d = F.to_date(F.col(cfg['date_col']))
        one = lambda c: F.when(c, 1).otherwise(0)
        aggs = [F.count(F.lit(1)).alias('txn_cnt')]
        if has_s:
            aggs.append(F.sum(one(F.expr(cfg['susp_cond']))).alias('susp_cnt'))
        if has_d:
            obs = F.col(cfg['obs_col']).cast('int') == 1
            aggs += [F.sum(one(obs & (F.col(cfg['def_col']).cast('int') == 1))).alias('def_cnt'),
                     F.sum(one(obs)).alias('obs_cnt')]
        if has_a:
            aggs.append(F.sum(F.col(cfg['amount_col']).cast('double')).alias('loan_amt'))
        daily = (df.where(d.between(str(start.date()), str(st['a_e'].date())) & F.col(cfg['merchant_col']).isNotNull())
                 .groupBy(F.col(cfg['merchant_col']).cast('string').alias('merchant'), d.alias('day')).agg(*aggs).toPandas())
        cols = [c for c in ['txn_cnt', 'susp_cnt', 'def_cnt', 'obs_cnt', 'loan_amt'] if c in daily.columns]
        if not len(det):
            for c in cols:
                det[c] = pd.Series(dtype=float)
            return
        sellers = pd.Index(sorted(set(det['merchant']) | set(daily['merchant'])))
        n_days = (st['a_e'] - start).days + 1
        di = (pd.to_datetime(daily['day']) - start).dt.days.values
        si = sellers.get_indexer(daily['merchant'])
        rs = sellers.get_indexer(det['merchant'])
        lo = np.clip((pd.to_datetime(det['recent_start']) - start).dt.days.values, 0, n_days)
        hi = np.clip((pd.to_datetime(det['recent_end']) - start).dt.days.values + 1, 0, n_days)
        for c in cols:
            M = np.zeros((len(sellers), n_days + 1))
            np.add.at(M, (si, di + 1), daily[c].fillna(0).values.astype(float))
            M = np.cumsum(M, axis=1)
            v = M[rs, hi] - M[rs, lo]
            det[c] = np.round(v, 2) if c == 'loan_amt' else v.astype(np.int64)
        _log(f"      added {', '.join(cols)} (recent window, by transaction)")

    def outcomes():
        """Transactions in the recent window of fired days / alerts, per rule, against the rest of the
        anchor range: counts by transaction and by distinct client (exact, each client once per rule)."""
        a_s, a_e = st['a_s'], st['a_e']
        rules, iv = _intervals(st['detail'][st['detail']['unit'] != 'ratio'], comparisons)
        iv['start'] = iv['start'].clip(lower=a_s); iv['end'] = iv['end'].clip(upper=a_e)
        iv = iv[iv['start'] <= iv['end']]
        has_s, has_d = bool(cfg['susp_cond']), bool(cfg['def_col'] and cfg['obs_col'])
        d = F.to_date(F.col(cfg['date_col']))
        one = lambda c: F.when(c, 1).otherwise(0)
        T = df.where(d.between(str(a_s.date()), str(a_e.date()))).select(
            F.col(cfg['merchant_col']).cast('string').alias('_m'), d.alias('_d'),
            F.col(cfg['customer_col']).cast('string').alias('_c'),
            (one(F.expr(cfg['susp_cond'])) if has_s else F.lit(0)).alias('_s'),
            (one(F.col(cfg['obs_col']).cast('int') == 1) if has_d else F.lit(0)).alias('_o'),
            (one((F.col(cfg['obs_col']).cast('int') == 1) & (F.col(cfg['def_col']).cast('int') == 1))
             if has_d else F.lit(0)).alias('_x')).persist()
        tx = lambda: [F.count(F.lit(1)).alias('txn'), F.sum('_s').alias('susp_txn'),
                      F.sum('_o').alias('obs_txn'), F.sum('_x').alias('def_txn')]
        tot = T.agg(*tx()).toPandas().iloc[0]
        per_c = T.groupBy('_c').agg(F.count(F.lit(1)).alias('n'), F.sum('_s').alias('ns'),
                                    F.sum('_o').alias('no'), F.sum('_x').alias('nx'))
        cl = per_c.agg(F.count(F.lit(1)).alias('client'), F.sum(one(F.col('ns') > 0)).alias('susp_client'),
                       F.sum(one(F.col('no') > 0)).alias('obs_client'),
                       F.sum(one(F.col('nx') > 0)).alias('def_client')).toPandas().iloc[0]
        allr = {**{k: int(tot[k] or 0) for k in ['txn', 'susp_txn', 'obs_txn', 'def_txn']},
                **{k: int(cl[k] or 0) for k in ['client', 'susp_client', 'obs_client', 'def_client']}}
        cov_t = cov_c = full = pd.DataFrame(columns=['rid', 'basis'])
        if len(iv):
            I = spark.createDataFrame(pd.DataFrame({'rid': iv['rid'].astype(int), 'basis': iv['basis'].astype(str),
                                                    '_im': iv['merchant'].astype(str),
                                                    '_is': iv['start'].dt.strftime('%Y-%m-%d'),
                                                    '_ie': iv['end'].dt.strftime('%Y-%m-%d')}))
            I = I.select('rid', 'basis', '_im', F.to_date('_is').alias('_is'), F.to_date('_ie').alias('_ie'))
            C = T.join(F.broadcast(I), (T['_m'] == I['_im']) & T['_d'].between(I['_is'], I['_ie'])).persist()
            cov_t = C.groupBy('rid', 'basis').agg(*tx()).toPandas()
            cc = C.groupBy('rid', 'basis', '_c').agg(F.count(F.lit(1)).alias('k'), F.sum('_s').alias('ks'),
                                                     F.sum('_o').alias('ko'), F.sum('_x').alias('kx'))
            cov_c = cc.groupBy('rid', 'basis').agg(
                F.count(F.lit(1)).alias('client'), F.sum(one(F.col('ks') > 0)).alias('susp_client'),
                F.sum(one(F.col('ko') > 0)).alias('obs_client'), F.sum(one(F.col('kx') > 0)).alias('def_client')).toPandas()
            # a client is outside the events if they have at least one transaction (of that kind) outside them
            full = cc.join(per_c, '_c').groupBy('rid', 'basis').agg(
                F.sum(one(F.col('k') == F.col('n'))).alias('client'),
                F.sum(one((F.col('ns') > 0) & (F.col('ks') == F.col('ns')))).alias('susp_client'),
                F.sum(one((F.col('no') > 0) & (F.col('ko') == F.col('no')))).alias('obs_client'),
                F.sum(one((F.col('nx') > 0) & (F.col('kx') == F.col('nx')))).alias('def_client')).toPandas()
            C.unpersist()
        T.unpersist()
        cnt = ['txn', 'client', 'susp_txn', 'susp_client', 'obs_txn', 'obs_client', 'def_txn', 'def_client']
        look = lambda tab, rid, basis: (tab[(tab['rid'] == rid) & (tab['basis'] == basis)].iloc[0]
                                        if len(tab) and ((tab['rid'] == rid) & (tab['basis'] == basis)).any() else None)
        kind = kinds
        rows = []
        for _, ru in rules.iterrows():
            for basis, other in [('fired', 'not_fired'), ('alert', 'not_alerted')]:
                t_, c_, f_ = look(cov_t, ru['rid'], basis), look(cov_c, ru['rid'], basis), look(full, ru['rid'], basis)
                inn = {k: int(t_[k]) if t_ is not None else 0 for k in ['txn', 'susp_txn', 'obs_txn', 'def_txn']}
                inn.update({k: int(c_[k]) if c_ is not None else 0 for k in ['client', 'susp_client', 'obs_client', 'def_client']})
                out = {k: allr[k] - inn[k] for k in ['txn', 'susp_txn', 'obs_txn', 'def_txn']}
                out.update({k: allr[k] - (int(f_[k]) if f_ is not None else 0)
                            for k in ['client', 'susp_client', 'obs_client', 'def_client']})
                for grp, v in [(basis, inn), (other, out)]:
                    r = {c: ru[c] for c in ['metric', 'comparison', 'unit', 'test']}
                    r.update(rule_type=kind.get(ru['metric'], 'flag'), group=grp, **{k: v[k] for k in cnt})
                    rows.append(r)
        o = pd.DataFrame(rows)
        if len(o):
            dv = lambda a, b: (o[a] / o[b].where(o[b] > 0)).round(4)
            o['susp_rate_txn'], o['susp_rate_client'] = dv('susp_txn', 'txn'), dv('susp_client', 'client')
            o['def_rate_txn'], o['def_rate_client'] = dv('def_txn', 'obs_txn'), dv('def_client', 'obs_client')
            if not has_s:
                o = o.drop(columns=['susp_txn', 'susp_client', 'susp_rate_txn', 'susp_rate_client'])
            if not has_d:
                o = o.drop(columns=['obs_txn', 'obs_client', 'def_txn', 'def_client', 'def_rate_txn', 'def_rate_client'])
        st['outcomes'] = o
        _log(f"      {len(iv):,} seller day ranges; outcomes for {len(rules)} rules")

    def summary():
        st['summary'] = _summary(st['detail'][st['detail']['unit'] != 'ratio'], st['fam'], st['n_days'], comparisons,
                                 [{'name': k, 'kind': v} for k, v in kinds.items()], st['susp'], st['loans'],
                                 st['a_s'], st['a_e'], int(cfg['lift_days']))
        cols = ['anchor', 'recent_start', 'recent_end', 'ref_start', 'ref_end', 'merchant', 'peer_group', 'metric',
                'comparison', 'unit', 'test', 'a', 'b', 'c', 'd', 'share_recent', 'share_ref', 'odds_ratio', 'or_lo',
                'or_hi', 'p', 'q', 'n_tests', 'peer_sellers', 'fired', 'alert'] + \
               [c for c in ['z_raw', 'z_std', 'mp_per_day', 'ref_per_day'] if c in st['detail'].columns] + \
               [c for c in ['txn_cnt', 'susp_cnt', 'def_cnt', 'obs_cnt', 'loan_amt'] if c in st['detail'].columns]
        st['detail'] = st['detail'][cols].sort_values(['anchor', 'p']).reset_index(drop=True)

    fns = [check, anchors] + ([thresholds] if rel else []) + [tests_for(u) for u in units] + \
          ([money_step] if money else []) + [fisher, alerts] + ([ratio_step] if ratio else []) + \
          [labels, row_totals, outcomes, summary]
    for i, (name, fn) in enumerate(zip(steps, fns), 1):
        try:
            step(i, name, fn)
        except Exception as e:
            first = (str(e).strip().splitlines() or [type(e).__name__])[0]
            _log(f"\nFAILED at step {i}/{len(steps)}: {name}: {first}")
            rest = steps[i:]
            if rest:
                _log(f"  not run: {', '.join(rest)}")
            res.update(failed_step=name, error=str(e), failed=[name])
            return res
    res.update(ok=True, detail=st['detail'], summary=st['summary'], outcomes=st['outcomes'], z_bands=st.get('z_bands'))
    _log(f"\nDone in {time.time() - t0:.0f}s: {len(st['detail']):,} detail rows, {len(st['summary'])} rules.")
    return res
